#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char *argv[]) {
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }
    char *endptr;
    long shift = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0') {
        puts("USAGE");
        return 0;
    }
    int s = (int)shift;
    s = ((s % 26) + 26) % 26; // normalize to 0..25
    const char *src = argv[2];
    for (size_t i = 0; src[i] != '\0'; ++i) {
        unsigned char c = src[i];
        if (c >= 'A' && c <= 'Z') {
            putchar(((c - 'A' + s) % 26) + 'A');
        } else if (c >= 'a' && c <= 'z') {
            putchar(((c - 'a' + s) % 26) + 'a');
        } else {
            putchar(c);
        }
    }
    putchar('\n');
    return 0;
}
